45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email validation: a non-empty local part, a single '@', and a
65	     * domain with at least one dot-separated label ending in a letter-only TLD.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
69	
70	    /** Dedicated audit logger for owner lifecycle side-effects. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    /**
92	     * Normalise a raw telephone number to E.164 form.
93	     *
94	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
95	     * code are kept when present; otherwise country code '+61' is assumed and a
96	     * single leading '0' is dropped from the national digits. The result must have
97	     * between 8 and 15 digits after the '+'.
98	     *
99	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
100	     */
101	    static String toE164(String raw) {
102	        if (raw == null) {
103	            return null;
104	        }
105	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
106	        String digits;
107	        if (cleaned.startsWith("+")) {
108	            digits = cleaned.substring(1);
109	        } else {
110	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
111	            digits = "61" + national;
112	        }
113	        if (!digits.matches("[0-9]{8,15}")) {
114	            return null;
115	        }
116	        return "+" + digits;
117	    }
118	
119	    /**
120	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
121	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
122	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
123	     * input normalises to the empty string.
124	     */
125	    private static String normaliseIdentity(String value) {
126	        if (value == null) {
127	            return "";
128	        }
129	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
130	    }
131	
132	    /**
133	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
134	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
135	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
136	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
137	     * that is both stored and used for every address comparison.
138	     */
139	    static String normaliseAddress(String value) {
140	        if (value == null) {
141	            return "";
142	        }
143	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
144	        if (collapsed.isEmpty()) {
145	            return "";
146	        }
147	        String[] tokens = collapsed.split(" ");
148	        StringBuilder result = new StringBuilder();
149	        for (int i = 0; i < tokens.length; i++) {
150	            if (i > 0) {
151	                result.append(' ');
152	            }
153	            result.append(expandAddressAbbreviation(tokens[i]));
154	        }
155	        return result.toString();
156	    }
157	
158	    /**
159	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
160	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
161	     * returned unchanged.
162	     */
163	    private static String expandAddressAbbreviation(String token) {
164	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
165	        return switch (core) {
166	            case "ST" -> "STREET";
167	            case "RD" -> "ROAD";
168	            case "AVE" -> "AVENUE";
169	            default -> token;
170	        };
171	    }
172	
173	    /**
174	     * Derive the stable, shared household identifier for owners sharing a household. It is a
175	     * deterministic UUID over the normalised last-name and address, so every owner in the same
176	     * household resolves to the same value regardless of the order in which they were created.
177	     */
178	    private static String householdId(String lastNameKey, String addressKey) {
179	        String seed = lastNameKey + "�" + addressKey;
180	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
181	    }
182	
183	    /**
184	     * Build the customer code for a new owner as {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
185	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
186	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
187	     * owners already in that city at the time the owner was created.
188	     */
189	    private String nextCustomerCode(String city, String lastName) {
190	        String city3 = prefix3(city);
191	        String last3 = prefix3(lastName);
192	        String cityKey = normaliseIdentity(city);
193	        int sequence = (int) this.clinicService.findAllOwners().stream()
194	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
195	            .count() + 1;
196	        return String.format("%s-%s-%04d", city3, last3, sequence);
197	    }
198	
199	    /**
200	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
201	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
202	     */
203	    static LocalDate toBusinessDay(LocalDate date) {
204	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
205	            date = date.plusDays(1);
206	        }
207	        return date;
208	    }
209	
210	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
211	    private static String prefix3(String value) {
212	        String letters = value == null ? "" : value;
213	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
219	        Collection<Owner> owners;
220	        if (lastName != null) {
221	            owners = this.clinicService.findOwnerByLastName(lastName);
222	        } else {
223	            owners = this.clinicService.findAllOwners();
224	        }
225	        if (owners.isEmpty()) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner == null) {
236	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	        }
238	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
244	        String telephone = toE164(ownerFieldsDto.getTelephone());
245	        if (telephone == null) {
246	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
247	        }
248	        String email = ownerFieldsDto.getEmail();
249	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
250	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
251	        }
252	        String address = normaliseAddress(ownerFieldsDto.getAddress());
253	        if (address.isEmpty()) {
254	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
255	        }
256	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
257	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
258	        LocalDate registrationDate = toBusinessDay(effectiveDate);
259	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
260	            .map(Owner::getRegistrationDate)
261	            .filter(existing -> existing != null)
262	            .map(OwnerRestControllerV1::toBusinessDay)
263	            .filter(registrationDate::equals)
264	            .count();
265	        if (ownersCreatedThatDay >= 100) {
266	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
267	        }
268	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
269	        long ownersInCity = this.clinicService.findAllOwners().stream()
270	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
271	            .count();
272	        if (ownersInCity >= 50) {
273	            return new ResponseEntity<>(HttpStatus.CONFLICT);
274	        }
275	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
276	            .map(Owner::getTelephone)
277	            .map(OwnerRestControllerV1::toE164)
278	            .filter(existing -> existing != null)
279	            .anyMatch(telephone::equals);
280	        if (telephoneInUse) {
281	            return new ResponseEntity<>(HttpStatus.CONFLICT);
282	        }
283	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
284	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
285	        String addressKey = address;
286	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
287	            .filter(existing ->
288	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
289	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
290	            .toList();
291	        if (!householdMembers.isEmpty() && !sharesHousehold) {
292	            return new ResponseEntity<>(HttpStatus.CONFLICT);
293	        }
294	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
295	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
296	            .filter(existing ->
297	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
298	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
299	            .count();
300	        HttpHeaders headers = new HttpHeaders();
301	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
302	        owner.setNamesakeCount(namesakeCount);
303	        owner.setAddress(address);
304	        owner.setTelephone(telephone);
305	        owner.setEmail(email == null ? null : email.toLowerCase());
306	        owner.setRegistrationDate(registrationDate);
307	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
308	        if (sharesHousehold && !householdMembers.isEmpty()) {
309	            String householdId = householdId(lastNameKey, addressKey);
310	            owner.setHouseholdId(householdId);
311	            for (Owner member : householdMembers) {
312	                if (member.getHouseholdId() == null) {
313	                    member.setHouseholdId(householdId);
314	                    this.clinicService.saveOwner(member);
315	                }
316	            }
317	        }
318	        this.clinicService.saveOwner(owner);
319	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
320	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
321	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
322	        headers.setLocation(UriComponentsBuilder.newInstance()
323	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
324	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
325	    }
326	
327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Override
329	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
330	        String telephone = toE164(ownerFieldsDto.getTelephone());
331	        if (telephone == null) {
332	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
333	        }
334	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
335	        if (currentOwner == null) {
336	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
337	        }
338	        String email = ownerFieldsDto.getEmail();
339	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
340	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
341	        }
342	        currentOwner.setAddress(ownerFieldsDto.getAddress());
343	        currentOwner.setCity(ownerFieldsDto.getCity());
344	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
345	        currentOwner.setLastName(ownerFieldsDto.getLastName());
346	        currentOwner.setTelephone(telephone);
347	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
348	        this.clinicService.saveOwner(currentOwner);
349	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
350	    }
351	
352	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
353	    @Transactional
354	    @Override
355	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
356	        Owner owner = this.clinicService.findOwnerById(ownerId);
357	        if (owner == null) {
358	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	        }
360	        this.clinicService.deleteOwner(owner);
361	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
367	        Owner owner = this.clinicService.findOwnerById(ownerId);
368	        if (owner == null) {
369	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	        }
371	        HttpHeaders headers = new HttpHeaders();
372	        Pet pet = petMapper.toPet(petFieldsDto);
373	        owner.setId(ownerId);
374	        pet.setOwner(owner);
375	        pet.getType().setName(null);
376	        this.clinicService.savePet(pet);
377	        PetDto petDto = petMapper.toPetDto(pet);
378	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
379	            .buildAndExpand(pet.getId()).toUri());
380	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
386	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
387	        if (currentOwner != null) {
388	            Pet currentPet = this.clinicService.findPetById(petId);
389	            if (currentPet != null) {
390	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
391	                currentPet.setName(petFieldsDto.getName());
392	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
393	                this.clinicService.savePet(currentPet);
394	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
395	            }
396	        }
397	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	    }
399	
400	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
401	    @Override
402	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
403	        HttpHeaders headers = new HttpHeaders();
404	        Visit visit = visitMapper.toVisit(visitFieldsDto);
405	        Pet pet = new Pet();
406	        pet.setId(petId);
407	        visit.setPet(pet);
408	        this.clinicService.saveVisit(visit);
409	        VisitDto visitDto = visitMapper.toVisitDto(visit);
410	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
411	            .buildAndExpand(visit.getId()).toUri());
412	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
413	    }
414	
415	
416	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
417	    @Override
418	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
419	        Owner owner = this.clinicService.findOwnerById(ownerId);
420	        if (owner != null) {
421	            Pet pet = owner.getPet(petId);
422	            if (pet != null) {
423	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
424	            }
425	        }
426	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
427	    }
428	}
